mapper.insert:

	SELECT
	'PAML'||
	LPAD(NVL(TO_NUMBER(SUBSTR(MAX(PAYMENT_RECEIPT),
	LENGTH('PAML' ) + 1)), 0) + 1, 6, '0')
	FROM PAYMENT_LIST

INSERT INTO PAYMENT_LIST (
PAYMENT_RECEIPT
, PAYMENT_NO
,
PAYMENT_START_DAY
, PAYMENT_AMOUNT
, PAYMENT_STATUS
, PAYMENT_APPROVALNUM
) VALUES (
#{paymentReceipt}
, #{paymentNo}
, #{paymentStartDay}
,
#{paymentAmount}
, #{paymentStatus}
, #{paymentApprovalnum}
)

mapper.select:
SELECT A.PAYMENT_RECEIPT, A.PAYMENT_NO AS A_PAYMENT_NO, A.PAYMENT_START_DAY, A.PAYMENT_AMOUNT, A.PAYMENT_STATUS, A.PAYMENT_APPROVALNUM,
B.PAYMENT_NO AS B_PAYMENT_NO, B.USER_ID, B.PRODUCT_NO, B.PAYMENT_METHOD, B.PAYMENT_DATE, B.PAYMENT_PAY, B.TOSS_PAYMENT_KEY
FROM PAYMENT_LIST A INNER JOIN PAYMENT B ON A.PAYMENT_NO = B.PAYMENT_NO WHERE B.USER_ID = #{userId}

mapper.update:
UPDATE PAYMENT_LIST
SET
PAYMENT_NO = #{paymentNo}
,
PAYMENT_START_DAY = #{paymentStartDay}
, PAYMENT_AMOUNT =
#{paymentAmount}
, PAYMENT_STATUS = #{paymentStatus}
,
PAYMENT_APPROVALNUM = #{paymentApprovalnum}
WHERE PAYMENT_RECEIPT =
#{paymentReceipt}
